                ["date" => "19.04.2021", "text" => "Herkese iyi günler, Berlin’de suan Fsp siz Zusage alırsak geçici Berufserlaubnis alabiliyor muyuz, bilgisi olan var mı acaba ?"],
                ["date" => "19.07.2021", "text" => "Arkadaşlar Hamburg’da bildiğiniz uygun fiyatlı çevirmen var mı?"],
                ["date" => "11.12.2021", "text" => "Iyi günler. Aramızda Berlin'de Kinderarzt olarak görev yapan var mı acaba?"],
                ["date" => "23.01.2022", "text" => "Herkese iyi akşamlar dil kursu için frankfurt veya çevresinde olan varsa özelden yazabilir mi ?"],
                ["date" => "01.02.2022", "text" => "Arkadaslar alman konsoloslugunda ve ya berlin buyukelciliginde apostil islemleri oluyor mu? Yoksa sadece Turkiyede mi oluyor acaba ?"],
                ["date" => "05.02.2022", "text" => "Herkese merhaba frankfurt veya çevresinde dil kursu yapan var mı? Varsa özelden yazabilir mi?"],
                ["date" => "11.03.2022", "text" => "Berlin ya da Bayern’de konaklama yeri sağlayan ya da yurtla anlaşmalı önerebileceğiniz fsp kursu var mı ?"],
                ["date" => "11.04.2022", "text" => "Frankfurt civarında uygun bir dil kursu arıyorum.Bana acil kayıt belgesi lazım.Yardımcı olabilir misiniz?"],
                ["date" => "28.06.2022", "text" => "Bremen - Hamburg - Hannover ( Kuzey Almanya) için bir grup varmı ?"],
                ["date" => "23.08.2022", "text" => "Herkese merhaba, Freiburg'ta B2 ve FSP için kurs önerebilecek biri varsa sevinirim?"],
                ["date" => "13.09.2022", "text" => "Arkadaşlar merhaba , Stuttgart çevresi uygun çevirmen önerebilir misiniz ?"],
                ["date" => "20.10.2022", "text" => "Iyi akşamlar,Hamburg için grup varsa ekleyebilir misiniz beni ?"],
                ["date" => "04.11.2022", "text" => "Arkadaşlar Berlin de Gutachten süreci için belgeler Bohn a mi gönderiliyor?"],
                ["date" => "07.11.2022", "text" => "Arkadaşlar Merhaba Freiburg için 5-30 haziran tarihleri arasında kalacak bir yurt veya kiralık bir daire arıyorum. Bildiğiniz bir yer varsa öneride bulanabilir misiniz?"],
                ["date" => "08.11.2022", "text" => "Arkadaşlar merhaba. Berlin eyaleti denklik işlemleri için gerekli evrak listesini paylaşabilirmisiniz?"],
                ["date" => "22.01.2023", "text" => "Günaydın, Frankfurt am Main’de önerdiğiniz dil okulu var mı?"],
                ["date" => "15.07.2023", "text" => "Arkadaşlar 1 ay hospitation için Niedersachsen-Stade ye gideceğim. Hamburg-Stade arasında ailece kalabileceğimiz bir yer arıyorum. Yardımcı olabilecek olan var mı?"],
                ["date" => "09.08.2023", "text" => "Arkadaşlar Hamburg için bir grup var mıydı acaba ben bulamadım?"],
