                ["date" => "21.10.2021", "text" => "Tam olarak anlayamadım...ulusal vize için almanyadan mı bir sigorta yaptırmak gerekiyor. ?"],
                ["date" => "04.11.2021", "text" => "Arkadaşlar merhabalar, Almanya'da sigorta işlemlerini başlatırken Türkiyeden sigortalı olduğumuz süreyi gösteren bir belge istenildi mi kimseden ? E devletten SGK hizmet dökümü yeterli olur mu ?"],
                ["date" => "09.08.2022", "text" => "Diğer belgeleri Almanca mı verdiniz acaba? adli sicil kaydı, sigorta vs?"],
                ["date" => "17.01.2023", "text" => "Iyi akşamlar, 30 f vize için sigorta yaptırırken hospitasyon olduğuna dair ekstra bir ibareye gerek olur mu?"],
                ["date" => "01.08.2019", "text" => "Fintiba plus açtığımız taktirde extradan sigorta yaptırmaya gerek yok değil mi?"],
                ["date" => "29.02.2024", "text" => "4 aylık dil kursu için 6 aylık mı sigorta yapmalıyım bloke hesabım 6 ay olacak?"],
                ["date" => "25.04.2024", "text" => "Expatrio'dan sigorta yaptırdığımız halde ekstradan SGK A/T 11 istenmiyor, değil mi?"],
                ["date" => "27.04.2024", "text" => "Expatrio'dan sigorta yaptırdığımız halde ekstradan SGK A/T 11 isteniyor mu?"],
                ["date" => "23.09.2024", "text" => "İyi akşamlar, Türkiye ehliyeti üstüne araba alan oldu mu? Sigorta veya kayıt yaparken sorun oluyor mu?"],
                ["date" => "24.09.2024", "text" => "Herkese merhabalar , Almanya’da Anmeldungumuz olduğunda göz muayenesi olabiliyor muyuz? Hausarzt yönlendiriyor mu veya sigorta kapsamında oluyor mu bilen var mı acaba?"],
                ["date" => "10.06.2025", "text" => "Birçok şeyi kapsayan bir sigorta yaptırmak istesem ne yaptırmalıyım? Hospitasyon yaparken AOK'tan sigorta yaptırabiliyor muyum?"],
                ["date" => "02.01.2020", "text" => "Günaydın arkadaşlar. Dil kursu için Almanya ya gelecekler sigortasını Türkiye deki sigorta şirketlerinde yaptırsa Almanya da sorun yaşar mı bi hastalık durumunda?"],
                ["date" => "17.08.2022", "text" => "Sağlık sigortasını Türkiye de mi yaptırmak mantıklı yoksa Almanya da mı? Türkiye'de yaptırdığımız sigorta uzun süreli kalacaklar için sorun olur mu?"],
                ["date" => "05.06.2023", "text" => "fintiba'ya kayıt yaparken DAK sağlık sigortasını onaylamamı zorunlu tuttu. AOK sigortası yaptırmayı düşünüyordum ve şu an fintiba'nın DAK yaptığından da emin değilim. Benzer bir süreç yaşayan var mı?"],
                ["date" => "21.11.2023", "text" => "Almanya'da olan arkadaşlar, at11i onaylayıp sigorta kartı veren bir sigorta şirketi var mı?"],
                ["date" => "28.09.2022", "text" => "AT11 belgesi 25 yaşına kadar veriliyor, 25 yaşından sonra nereden yaptırabiliriz önerdiğiniz sigorta şirketi var mı ?"],
                ["date" => "01.10.2022", "text" => "Dr Walker , Expatio falan gereğinden fazla ücret çıkarıyor Allianz sigorta ile daha ucuz halledebiliyoruz ? Alllianz ile yaptıran arkadaşlar varöı?"],
                ["date" => "15.07.2024", "text" => "oturum uzatmak için Krankenversicherung isteniyor en uygun AOK mı yapıyor deneyimi olan yazabilir mi?"],
                ["date" => "08.10.2025", "text" => "İzninizle bişey sormak istiyorum, Çocuğum Almanya'da öğrenci ve sigorta olarak AT11 belgesi var, bu belge ile yarı zamanlı bir işte ekstra sigorta yapmadan çalışabilir mi?"],
                ["date" => "19.05.2023", "text" => "AT11 belgesi olan aok kayıt olan kronik rahatsızlığı olan arkadaşım Almanyada ilaç yazdırmaya gittiğinde 40 euro ödemiş ,parayı geri almak için Aok mı SGK ile mi iletişime geçmesi gerekiyor?"],
                ["date" => "03.08.2022", "text" => "Ama bana direk kabul verilmiş ve C1 sertifikasi ile sigorta belgesini gönder diyor. Benim dil sertifikam hiç yok. Ben şartlı kabul istiyorum başına böyle birşey gelen yokmu?"],
            ],
