                ["date" => "01.12.2021", "text" => "Iyi aksamlar arkadaslar.Hessende BE almak icin Zusage ve Anmeldung mutlakdirmi??"],
                ["date" => "20.01.2022", "text" => "Arkadaslar yeni geldim Berline . Ctesi . Burada anmeldung yapmak icin bi sure sinirlamasi varmi?"],
                ["date" => "13.04.2022", "text" => "Bayernden FSP randevusu almak için sadece B2 yeterli mi? Approbation başvurusu, anmeldung, zusage gibi seyler zorunlu mu?"],
                ["date" => "13.01.2023", "text" => "bw de fsp termini icin zusage veya orada anmeldung sarti var mi?"],
